AppProto AppLayerProtoDetectDetect(
    AppLayerProtoDetectThreadCtx *tctx,
    Flow *f,
    uint8_t *buf,
    uint32_t buflen,
    uint8_t ipproto,
    uint8_t direction)
{
    AppProto alproto = ALPROTO_UNKNOWN;

    /* Check if PM detection has completed and provide result */
    if (tctx->pm_skip_data != 1) {
        alproto = AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
        if (alproto != ALPROTO_UNKNOWN) {
            return alproto;
        }
    }

    /* Check if PP detection is needed */
    if (tctx->pp_appid != ALPROTO_UNKNOWN) {
        alproto = tctx->pp_appid;
        return alproto;
    }

    /* Check expectation list for detection */
    if (f->expectations != NULL) {
        alproto = AppLayerProtoDetectExpectation(f);
        if (alproto != ALPROTO_UNKNOWN) {
            return alproto;
        }
    }

    return ALPROTO_UNKNOWN;
}

AppProto AppLayerProtoDetectDetect(AppLayerProtoDetectThreadCtx *tctx,
                                   Flow *f,
                                   uint8_t *buf,
                                   uint32_t buflen,
                                   uint8_t ipproto,
                                   uint8_t direction) {
    AppProto alproto = ALPROTO_UNKNOWN;

    if (f->alproto != ALPROTO_UNKNOWN) {
        return f->alproto;
    }

    if (tctx->pm_proto_detect != NULL) {
        tctx->pm_proto_detect(tctx, f, buf, buflen, ipproto, direction, &alproto);
    }

    if (alproto != ALPROTO_UNKNOWN) {
        f->alproto = alproto;
        return alproto;
    }

    if (tctx->pp_proto_detect != NULL) {
        tctx->pp_proto_detect(tctx, f, buf, buflen, ipproto, direction, &alproto);
    }

    if (alproto != ALPROTO_UNKNOWN) {
        f->alproto = alproto;
        return alproto;
    }

    if (tctx->expectation_list != NULL) {
        tctx->expectation_list(tctx, f, &alproto);
    }

    if (alproto != ALPROTO_UNKNOWN) {
        f->alproto = alproto;
        return alproto;
    }

    f->alproto = ALPROTO_UNKNOWN;
    return ALPROTO_UNKNOWN;
}

AppProto AppLayerProtoDetect(const AppLayerProtoDetectThreadCtx *tctx, Flow *f,
                             uint8_t *buf, uint32_t buflen, uint8_t ipproto,
                             uint8_t direction) {
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!AppLayerProtoDetectPMCompleted(f)) {
        alproto = AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
        if (alproto != ALPROTO_UNKNOWN) {
            return alproto;
        }
    }

    if (AppLayerProtoDetectPPEnabled(tctx, ipproto)) {
        alproto = AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction);
        if (alproto != ALPROTO_UNKNOWN) {
            return alproto;
        }
    }

    if (AppLayerProtoDetectExpectationListCheck(f, ipproto)) {
        alproto = AppLayerProtoDetectExpectationGet(f, ipproto);
        if (alproto != ALPROTO_UNKNOWN) {
            return alproto;
        }
    }

    return ALPROTO_UNKNOWN;
}

AppProto AppLayerProtoDetectDetect(
    AppLayerProtoDetectThreadCtx *tctx,
    Flow *f,
    uint8_t *buf,
    uint32_t buflen,
    uint8_t ipproto,
    uint8_t direction)
{
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowPMInspectionDone(f, direction)) {
        if (AppLayerProtoDetectPMInspect(tctx, f, buf, buflen, ipproto, direction, &alproto) != 0) {
            return ALPROTO_UNKNOWN;
        }
    }

    if (alproto == ALPROTO_UNKNOWN) {
        if (AppLayerProtoDetectPPDetect(tctx, f, ipproto, direction, &alproto) != 0) {
            return ALPROTO_UNKNOWN;
        }
    }

    if (alproto == ALPROTO_UNKNOWN) {
        if (AppLayerProtoDetectExpectationListCheck(tctx, f, ipproto, direction, &alproto) != 0) {
            return ALPROTO_UNKNOWN;
        }
    }

    if (alproto == ALPROTO_DCERPC) {
        if (AppLayerProtoDetectDCERPCHandlerCheck(f, direction)) {
            alproto = ALPROTO_SMB;
        }
    }

    return alproto;
}

AppProto AppLayerProtoDetectDetect(AppLayerProtoDetectThreadCtx *tctx, Flow *f,
                                   uint8_t *buf, uint32_t buflen, uint8_t ipproto,
                                   uint8_t direction) {
    AppProto alproto = ALPROTO_UNKNOWN;

    if (f->alproto == ALPROTO_UNKNOWN) {
        if (!FlowPMInspectionDone(f, direction)) {
            AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
            FlowSetPMInspectionDone(f, direction);
        }

        if (f->alproto == ALPROTO_UNKNOWN) {
            if (!FlowPPInspectionDone(f, direction)) {
                AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction);
                FlowSetPPInspectionDone(f, direction);
            }

            if (f->alproto == ALPROTO_UNKNOWN) {
                alproto = AppLayerProtoDetectExpectation(f, ipproto, direction);
            }
        }

        alproto = f->alproto;
    }

    if (alproto == ALPROTO_DCERPC) {
        if (!FlowCheckSupportsDCE(f))
            alproto = ALPROTO_UNKNOWN;
    }

    return alproto;
}
